ALTER TABLE "global_index_registry" ADD COLUMN IF NOT EXISTS "display_name" TEXT, ADD COLUMN IF NOT EXISTS "provider_external_id" TEXT, ADD COLUMN IF NOT EXISTS "official_source_url" TEXT, ADD COLUMN IF NOT EXISTS "index_type" TEXT NOT NULL DEFAULT 'OTHER', ADD COLUMN IF NOT EXISTS "verification_status" TEXT NOT NULL DEFAULT 'UNVERIFIED', ADD COLUMN IF NOT EXISTS "terminated_at" DATE;
ALTER TABLE "global_index_candles" ADD COLUMN IF NOT EXISTS "source_record_id" TEXT, ADD COLUMN IF NOT EXISTS "source_url" TEXT, ADD COLUMN IF NOT EXISTS "source_type" TEXT NOT NULL DEFAULT 'SUPPLEMENTAL', ADD COLUMN IF NOT EXISTS "verification_status" TEXT NOT NULL DEFAULT 'UNVERIFIED', ADD COLUMN IF NOT EXISTS "license_status" TEXT NOT NULL DEFAULT 'SUPPLEMENTAL_UNVERIFIED', ADD COLUMN IF NOT EXISTS "currency" TEXT;
CREATE TABLE IF NOT EXISTS "global_index_aliases" ("index_id" TEXT NOT NULL,"legacy_symbol" TEXT NOT NULL,"provider" TEXT NOT NULL,"provider_symbol" TEXT,"mapping_method" TEXT NOT NULL,"verified_at" TIMESTAMP(3),"source" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("index_id","legacy_symbol","provider"));
CREATE INDEX IF NOT EXISTS "global_index_aliases_legacy_symbol_idx" ON "global_index_aliases"("legacy_symbol");
CREATE TABLE IF NOT EXISTS "global_index_snapshots" ("index_id" TEXT PRIMARY KEY,"current_level" DECIMAL(30,10) NOT NULL,"previous_close" DECIMAL(30,10),"change" DECIMAL(30,10),"change_percent" DECIMAL(20,8),"high_52_week" DECIMAL(30,10),"low_52_week" DECIMAL(30,10),"as_of_date" TIMESTAMP(3) NOT NULL,"source" TEXT NOT NULL,"freshness_status" TEXT NOT NULL,"verification_status" TEXT NOT NULL,"license_status" TEXT NOT NULL,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "global_index_methodologies" ("index_id" TEXT PRIMARY KEY,"methodology_url" TEXT NOT NULL,"methodology_title" TEXT,"provider" TEXT NOT NULL,"base_date" DATE,"base_value" DECIMAL(24,6),"launch_date" DATE,"calculation_type" TEXT,"weighting_method" TEXT,"review_frequency" TEXT,"rebalance_frequency" TEXT,"source" TEXT NOT NULL,"source_url" TEXT,"as_of_date" TIMESTAMP(3) NOT NULL,"verification_status" TEXT NOT NULL,"license_status" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "global_index_constituents" ("index_id" TEXT NOT NULL,"constituent_key" TEXT NOT NULL,"security_id" TEXT,"constituent_name" TEXT NOT NULL,"ticker" TEXT,"isin" TEXT,"weight" DECIMAL(20,10),"as_of_date" DATE NOT NULL,"effective_from" DATE,"effective_to" DATE,"source" TEXT NOT NULL,"source_record_id" TEXT,"license_status" TEXT NOT NULL,"verification_status" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("index_id","constituent_key","as_of_date","source"));
CREATE INDEX IF NOT EXISTS "global_index_constituents_index_id_as_of_date_idx" ON "global_index_constituents"("index_id","as_of_date");
CREATE TABLE IF NOT EXISTS "global_index_events" ("id" TEXT PRIMARY KEY,"index_id" TEXT NOT NULL,"event_type" TEXT NOT NULL,"announcement_date" DATE,"effective_date" DATE NOT NULL,"event_description" TEXT,"source" TEXT NOT NULL,"source_record_id" TEXT,"source_url" TEXT,"verification_status" TEXT NOT NULL,"license_status" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("index_id","event_type","effective_date","source"));
CREATE INDEX IF NOT EXISTS "global_index_events_index_id_effective_date_idx" ON "global_index_events"("index_id","effective_date");
CREATE TABLE IF NOT EXISTS "global_index_analytics" ("index_id" TEXT NOT NULL,"metric" TEXT NOT NULL,"as_of_date" DATE NOT NULL,"value" DECIMAL(30,12),"source" TEXT NOT NULL DEFAULT 'DERIVED_CANONICAL_HISTORY',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("index_id","metric","as_of_date"));
CREATE INDEX IF NOT EXISTS "global_index_analytics_metric_as_of_date_idx" ON "global_index_analytics"("metric","as_of_date");
